SELECT percent_rank() OVER (ORDER BY instability_score) AS percentile_rank, top_decile_los, avg_mortality_duration FROM instability JOIN renal_replacement ON instability.subject_id = renal_replacement.subject_id JOIN female_patients ON instability.subject_id = female_patients.subject_id JOIN top_decile ON instability.subject_id = top_decile.subject_id WHERE instability_score = 65;